        if isinstance(v, dict) and len(v) == 1 and next(iter(v)) in ("Ref", "Fn::Sub", "Fn::GetAtt"):
            key, v = next(iter(v.items()))  # long form: {Ref: X} / {Fn::Sub: ...} / {Fn::GetAtt: [X, Y]}
            if key == "Fn::GetAtt" and isinstance(v, list):
